/* Lot 105: the geometry of box scrollers the engine hands back to the reader (generated by scripts/lot105_gen.py; expectations from scripts/lot105_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "webeng.h"

static we_doc_t g_doc;
static we_forms_t g_forms;
static wf_geom_t g_g;
static char g_html[4096], g_o[200];

/* the page laid out at 320 x 480 with a forms state (box offsets
 * kept by id) */
static int page(const char *body) {
    snprintf(g_html, sizeof(g_html), "<html><body style='margin:0'>%s</body></html>", body);
    we_forms_init(&g_forms);
    we_set_forms(&g_doc, &g_forms);
    if (we_parse(&g_doc, g_html, (int)strlen(g_html)) || we_style(&g_doc) || we_layout_viewport(&g_doc, 320, 480))
        return -9;
    return 0;
}

/* laid out again (the box offset applied), the root scrolled, fed */
static int feed(int y) {
    if (we_layout_viewport(&g_doc, 320, 480)) return -9;
    (void)we_scroll(&g_doc, y);
    memset(&g_g, 0x5a, sizeof(g_g));
    return we_geom_feed(&g_doc, "wg", &g_g);
}

static const char *root(void) {
    snprintf(g_o, sizeof(g_o), "%d %d %d %d %d", g_g.vw, g_g.vh, g_g.rg_x, g_g.rg_y, g_g.sc_y);
    return g_o;
}

static const char *box(int k) {
    const wf_geom_box_t *b = &g_g.box[k];
    if (!b->ok) return "none";
    snprintf(g_o, sizeof(g_o), "%d %d %d+%d %d+%d vp %d/%d sc %d/%d rg %d/%d sv %d sm %d own %d/%d/%d", b->root,
             b->bvert, b->b_off, b->b_size, b->i_off, b->i_size, b->vp_b, b->vp_i, b->sc_b, b->sc_i, b->rg_b,
             b->rg_i, b->sv, b->sm, b->s_vp, b->s_sc, b->s_rg);
    return g_o;
}

